import fs from 'node:fs'; import path from 'node:path';
const OUT = process.argv[2]; fs.mkdirSync(OUT,{recursive:true});
const root = process.env.PLAYWRIGHT_BROWSERS_PATH;
const d = fs.readdirSync(root).find(x=>x.startsWith('chromium-')); const base=path.join(root,d,'chrome-mac-arm64');
const app=fs.readdirSync(base).find(f=>f.endsWith('.app'));
const browser = await chromium.launch({executablePath: path.join(base,app,'Contents/MacOS',app.replace('.app',''))});
const ctx = await browser.newContext({viewport:{width:1280,height:800},deviceScaleFactor:2});
const page = await ctx.newPage();
await page.goto('http://localhost:5230/');
await page.waitForSelector('[data-test="conversation-row-conv-01"]');
await page.keyboard.press('Enter');
await page.waitForSelector('[data-test="reader-messages"]');
await new Promise(r=>setTimeout(r,500));
// per-frame sampler
await page.evaluate(() => {
  window.__frames = [];
  const t0 = performance.now();
  const tick = () => {
    const q = (s) => document.querySelector(s);
    window.__frames.push({
      t: Math.round(performance.now()-t0),
      subject: q('.reader-subject')?.textContent ?? null,
      loading: !!q('[data-test="reader-loading"]'),
      headerIcons: document.querySelectorAll('.header-glyph[data-test="reader-archive-toggle"], .header-glyph[data-test="files-links"], .header-glyph[data-test="prepare-reply"]').length,
      contact: q('[data-test="contact-name"]')?.textContent ?? q('.contact-pane')?.textContent?.trim().slice(0,30) ?? null,
      focus: document.activeElement?.getAttribute('data-test') ?? document.activeElement?.tagName,
      scroll: q('.reader-scroll')?.scrollTop ?? null,
      bodyH: Math.round(q('.reader-scroll')?.scrollHeight ?? 0),
    });
    requestAnimationFrame(tick);
  };
  requestAnimationFrame(tick);
});
await new Promise(r=>setTimeout(r,300));
await page.evaluate(()=>{window.__mark=window.__frames.length});
await page.keyboard.press('j');
await new Promise(r=>setTimeout(r,150)); await page.screenshot({path:path.join(OUT,'jk-mid-load.png')});
await new Promise(r=>setTimeout(r,700)); await page.screenshot({path:path.join(OUT,'jk-after-load.png')});
const frames = await page.evaluate(()=>window.__frames.slice(window.__mark-1));
// collapse to state changes
let last=''; const rows=[];
for (const f of frames){ const k=JSON.stringify({s:f.subject,l:f.loading,h:f.headerIcons,c:f.contact,f:f.focus,b:f.bodyH}); if(k!==last){rows.push(f); last=k;} }
console.log(JSON.stringify(rows,null,1));
await browser.close();

