    key('j');
    await settle();
    await vi.advanceTimersByTimeAsync(READER_LOADING_DELAY_MS + 1);
    await settle();
    expect(loadingShown()).toBe(true);
    expect(focusName()).toBe('reader');
    slow.resolve(await detailOf('read-02'));
    await settle();
    expect(focusName()).toBe('message-toggle-read-02-m1');
