    key('j');
    await settle();
    expect((w.get('[data-test="reader-scroll"]').element as HTMLElement).scrollTop).toBe(0);
    key('k');
    await settle();
    expect(subject()).toBe('Reader journey thread');
    expect((w.get('[data-test="reader-scroll"]').element as HTMLElement).scrollTop).toBe(150);
  });
});

